*{box-sizing:border-box}.ct{min-height:100vh;padding:18px;max-width:1450px;margin:auto}.ct-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.ct-brand{display:flex;align-items:center;gap:11px}.ct-orb{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;background:radial-gradient(circle at 30% 25%,#fff,#7c5cff 45%,#24144e);box-shadow:0 0 38px rgba(124,92,255,.28)}.ct-head h1{margin:0;font-size:27px}.ct-head p{margin:3px 0 0;color:var(--muted)}.ct-btn,.ct-mini,.ct-back{border:1px solid var(--line);background:rgba(255,255,255,.045);color:#fff;border-radius:10px;padding:9px 12px;cursor:pointer}.ct-btn.primary{background:linear-gradient(135deg,#7359e8,#398cff);border-color:transparent}.ct-back{text-decoration:none}.ct-hero,.ct-stage,.ct-side,.ct-card,.ct-panel,.ct-settings,.ct-log{border:1px solid var(--line);border-radius:17px;background:var(--panel);box-shadow:0 14px 45px rgba(0,0,0,.15)}.ct-hero{padding:18px;margin-bottom:15px}.ct-hero h2{margin:0 0 6px;font-size:22px}.ct-hero p{margin:0;color:var(--muted);line-height:1.5}.status{display:inline-flex;margin-top:10px;color:var(--ok);background:rgba(87,226,173,.08);border-radius:999px;padding:5px 9px;font-size:11px}.workspace{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(290px,.7fr);gap:15px}.ct-stage,.ct-side{padding:14px}.stage-head,.side-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:10px}.stage-head h3,.side-head h3{margin:0;font-size:15px}.stage-head small,.side-head small{color:var(--muted)}.screen{position:relative;aspect-ratio:16/9;border-radius:13px;overflow:hidden;background:radial-gradient(circle at 50% 35%,#1c2642,#080b13 70%);border:1px solid var(--line);display:grid;place-items:center}.screen video{width:100%;height:100%;object-fit:contain;display:none}.screen.demo video{display:block}.placeholder{text-align:center;color:var(--muted);padding:20px}.placeholder b{display:block;color:#fff;margin-bottom:5px}.screen.demo .placeholder{display:none}.live{position:absolute;left:9px;top:9px;z-index:3;background:#ff365d;padding:5px 8px;border-radius:999px;font-size:10px;display:none}.screen.demo .live{display:block}.chat-overlay{position:absolute;right:9px;bottom:9px;display:none;flex-direction:column;align-items:flex-end;gap:5px;width:min(48%,300px);z-index:3}.screen.chat-on .chat-overlay{display:flex}.msg{background:rgba(4,7,14,.8);backdrop-filter:blur(8px);border:1px solid var(--line);padding:6px 8px;border-radius:8px;font-size:10px;max-width:100%;opacity:var(--overlay,.92)}.donate{position:absolute;left:9px;bottom:9px;background:linear-gradient(135deg,#f0a84b,#ef4f7a);padding:8px 10px;border-radius:10px;font-size:11px;display:none;z-index:4}.screen.alert .donate{display:block}.bar{display:flex;flex-wrap:wrap;gap:7px;margin-top:9px}.ct-side textarea,.field input,.field select,.field textarea{width:100%;background:#0a0e19;color:#fff;border:1px solid var(--line);border-radius:9px;padding:9px;outline:none}.ct-side textarea{min-height:88px;resize:vertical}.result{margin-top:8px;padding:10px;border:1px solid var(--line);border-radius:9px;white-space:pre-wrap;min-height:44px;color:#dce4f2;font-size:12px;line-height:1.45}.tools{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px;margin-top:15px}.ct-card{padding:14px;min-height:160px;display:flex;flex-direction:column;transition:.18s}.ct-card.open{border-color:rgba(124,92,255,.55);box-shadow:0 0 0 1px rgba(124,92,255,.12),0 18px 45px rgba(0,0,0,.2)}.icon{width:37px;height:37px;border-radius:11px;display:grid;place-items:center;background:rgba(124,92,255,.11);font-size:18px;margin-bottom:9px}.ct-card h3{margin:0 0 4px;font-size:14px}.ct-card p{margin:0;color:var(--muted);font-size:11px;line-height:1.45;flex:1}.card-actions{display:flex;gap:7px;margin-top:10px}.ct-mini.active{color:var(--ok);border-color:rgba(87,226,173,.5)}.tool-panel{display:none;margin-top:10px;padding:12px;border:1px solid var(--line);border-radius:12px;background:rgba(5,8,15,.72)}.ct-card.open .tool-panel{display:block}.tool-panel h4{margin:0 0 9px;font-size:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.field label{display:block;color:var(--muted);font-size:10px;margin-bottom:4px}.field input,.field select,.field textarea{font-size:11px}.field textarea{min-height:70px;resize:vertical}.check{display:flex;align-items:center;gap:7px;color:#dce4f2;font-size:11px;padding-top:17px}.check input{width:auto}.settings{margin-top:15px;padding:14px}.settings h3{margin:0 0 10px;font-size:15px}.log{margin-top:15px;padding:12px;background:#080b13}.log-head{display:flex;justify-content:space-between;color:var(--muted);font-size:10px;margin-bottom:7px}.log-body{max-height:170px;overflow:auto;font:10px/1.5 ui-monospace,monospace;color:#b9c4d8}.log-body div{padding:2px 0}.note{margin-top:12px;padding:11px 13px;border:1px dashed rgba(124,92,255,.35);border-radius:12px;color:var(--muted);font-size:10px;line-height:1.5}@media(max-width:980px){.workspace{grid-template-columns:1fr}.tools{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.ct{padding:11px}.tools,.grid{grid-template-columns:1fr}.ct-head h1{font-size:22px}}
