<body class="dashboard-page">
<main class="ct">
<header class="ct-head"><div class="ct-brand"><div class="ct-orb">✦</div><div><h1>Creator Tools</h1><p>Evruni AI tools for streamers</p></div></div><a class="ct-back" href="/">← Evruni</a></header>
<section class="ct-hero"><div class="eyebrow">EVRUNI CREATOR</div><h2>Все инструменты — по нажатию, без фоновой нагрузки</h2><p>Нажми на любую карточку — под ней откроется её рабочая панель и настройки. Локальные функции работают в браузере; AI вызывается только по действию.</p><span class="status">● Local-first / event-driven</span></section>
<section class="workspace">
<div class="ct-stage"><div class="stage-head"><div><h3>🖥️ Демонстрация экрана</h3><small>Видео не отправляется на сервер</small></div><button class="ct-btn primary" id="share">Начать</button></div><div class="screen" id="screen"><span class="live">● LIVE PREVIEW</span><video id="video" autoplay muted playsinline></video><div class="placeholder"><b>Предпросмотр стрима</b>Выбери окно, вкладку или весь экран.</div><div class="chat-overlay"><div class="msg">👤 Привет, Evruni!</div><div class="msg">🔥 Крутой момент!</div><div class="msg">💬 Когда следующий стрим?</div></div><div class="donate" id="donate">💰 Донат +500 ₽ · Спасибо!</div></div><div class="bar"><button class="ct-mini" id="blur">🔞 Blur</button><button class="ct-mini" id="overlay">🎨 Overlay</button><button class="ct-mini" id="alert">🔔 Тест доната</button><button class="ct-mini" id="stop">⏹ Стоп</button></div></div>
<aside class="ct-side"><div class="side-head"><div><h3>⚡ Event Console</h3><small>Одна команда = один запрос</small></div><span class="status">● ready</span></div><textarea id="event" placeholder="Сообщение зрителя, момент или событие…"></textarea><div class="bar"><button class="ct-mini" data-ai="chatbot">💬 Ответ</button><button class="ct-mini" data-ai="moderate">🛡️ Модерация</button><button class="ct-mini" data-ai="copilot">🧠 Copilot</button><button class="ct-mini" data-ai="translate">🌍 Перевести</button></div><div class="result" id="result">Результат появится здесь.</div></aside>
</section>
<section class="tools" id="tools"></section>
<section class="settings"><h3>⚙️ Общие настройки</h3><div class="grid"><div class="field"><label>Язык AI</label><select id="lang"><option value="ru">Русский</option><option value="en">English</option><option value="de">Deutsch</option><option value="es">Español</option></select></div><div class="field"><label>Язык перевода</label><select id="target"><option>English</option><option>Russian</option><option>German</option><option>Spanish</option><option>French</option></select></div><div class="field"><label>Blur: <span id="bv">18</span> px</label><input id="br" type="range" min="0" max="32" value="18"></div><div class="field"><label>Overlay: <span id="ov">92</span>%</label><input id="orr" type="range" min="30" max="100" value="92"></div><div class="field"><label>Тестовый донат</label><input id="at" value="💰 Донат +500 ₽ · Спасибо!"></div><div class="field"><label>Алерт, секунд</label><input id="ad" type="number" min="1" max="15" value="4"></div><div class="check"><input id="ai" type="checkbox" checked><label>Разрешить AI</label></div><div class="check"><input id="local" type="checkbox" checked><label>Local-first</label></div></div><div class="bar"><button class="ct-mini" id="save">💾 Сохранить</button><button class="ct-mini" id="reset">↺ Сбросить</button></div></section>
<section class="log"><div class="log-head"><span>Event log</span><span id="count">0 событий</span></div><div class="log-body" id="log"></div></section>
<div class="note"><b>Нагрузка:</b> нет постоянного polling/WebSocket, фонового AI или загрузки видео. Voice Cleaner, Blur, Overlay, Alerts и Analytics работают локально. AI вызывается только после действия. Auto Clips создаёт лёгкую отметку момента, а не рендерит видео на сервере. Реальные Twitch/YouTube/Kick webhook-события подключаются отдельно.</div>
</main>
<script>
(()=>{
const API='/api/creator_tools.php',CSRF=document.querySelector('meta[name="csrf-token"]')?.content||'',STORE='evruni_creator_tools_v3';
const defaults={lang:'ru',target:'English',blur:18,overlay:92,alertText:'💰 Донат +500 ₽ · Спасибо!',alertDuration:4,ai:true,local:true};
const $=s=>document.querySelector(s),screen=$('#screen'),video=$('#video');let stream=null,mic=null,audio=null,events=0;
const toolData=[
['🎙️','Voice Cleaner','Локальное шумоподавление микрофона.','mic','Включить микрофон','Шумоподавление','noise'],
['💬','AI Chat Bot','Ответ зрителю только по событию.','chat','Спросить AI','Стиль ответа','chat'],
['🛡️','AI Moderator','Модерация нового сообщения по запросу.','moderation','Проверить сообщение','Строгость','moderation'],
['🎨','Chat Overlay','Чат поверх демонстрации экрана.','overlay','Включить Overlay','Прозрачность','overlay'],
['🔔','Smart Alerts','Тест доната, подписки или рейда локально.','alerts','Показать тестовый алерт','Тип события','alerts'],
['🌍','Live Translator','Перевод выбранной реплики по нажатию.','translator','Перевести текст','Язык перевода','translator'],
['🔞','Content Censor','Мгновенный Blur предпросмотра.','censor','Включить Blur','Сила Blur','censor'],
['✂️','Auto Clips','Отметка момента без тяжёлого рендера.','clips','Отметить момент','Название клипа','clips'],
['🧠','Stream Copilot','Одна полезная подсказка на одно событие.','copilot','Получить подсказку','Контекст','copilot'],
['📊','Stream Analytics','Локальная статистика текущей сессии.','analytics','Обновить статистику','Сессия','analytics'],
['📝','Stream Summary','Сводка завершённого стрима через AI.','summary','Создать Summary','Текст/заметки','summary'],
['📱','Shorts Maker','Hook, title, caption и hashtags по моменту.','shorts','Создать пакет Shorts','Момент','shorts']
];
function log(s){events++;$('#count').textContent=events+' событий';const d=document.createElement('div');d.textContent=new Date().toLocaleTimeString()+' · '+s;$('#log').prepend(d)}
function load(){try{return {...defaults,...JSON.parse(localStorage.getItem(STORE)||'{}')}}catch(e){return {...defaults}}}
function save(){const v={lang:$('#lang').value,target:$('#target').value,blur:+$('#br').value,overlay:+$('#orr').value,alertText:$('#at').value,alertDuration:+$('#ad').value,ai:$('#ai').checked,local:$('#local').checked};localStorage.setItem(STORE,JSON.stringify(v));apply(v);log('Настройки сохранены')}
function apply(v){$('#lang').value=v.lang;$('#target').value=v.target;$('#br').value=v.blur;$('#orr').value=v.overlay;$('#at').value=v.alertText;$('#ad').value=v.alertDuration;$('#ai').checked=v.ai;$('#local').checked=v.local;$('#bv').textContent=v.blur;$('#ov').textContent=v.overlay;screen.style.setProperty('--blur',v.blur+'px');screen.style.setProperty('--overlay',v.overlay/100);$('#donate').textContent=v.alertText}
apply(load());
$('#br').oninput=e=>{$('#bv').textContent=e.target.value;screen.style.setProperty('--blur',e.target.value+'px')};$('#orr').oninput=e=>{$('#ov').textContent=e.target.value;screen.style.setProperty('--overlay',e.target.value/100)};$('#save').onclick=save;$('#reset').onclick=()=>{localStorage.removeItem(STORE);apply(defaults);log('Настройки сброшены')};
$('#share').onclick=async()=>{if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;screen.classList.remove('demo');$('#share').textContent='Начать';log('Демонстрация остановлена');return}try{stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});video.srcObject=stream;screen.classList.add('demo');$('#share').textContent='Стоп';stream.getVideoTracks()[0].onended=()=>{$('#stop').click()};log('Экран выбран локально')}catch(e){log('Демонстрация отменена')}};
$('#stop').onclick=()=>{$('#share').click()};
$('#blur').onclick=()=>{screen.classList.toggle('blurred');$('#blur').classList.toggle('active');log('Blur '+(screen.classList.contains('blurred')?'включён':'выключен'))};
$('#overlay').onclick=()=>{screen.classList.toggle('chat-on');$('#overlay').classList.toggle('active');log('Chat Overlay '+(screen.classList.contains('chat-on')?'включён':'выключен'))};
$('#alert').onclick=()=>{screen.classList.add('alert');log('Тестовый донат показан');setTimeout(()=>screen.classList.remove('alert'),Math.max(1,+$('#ad').value)*1000)};
function localMic(){if(mic){mic.getTracks().forEach(t=>t.stop());mic=null;log('Voice Cleaner выключен');return}navigator.mediaDevices.getUserMedia({audio:{noiseSuppression:true,echoCancellation:true,autoGainControl:true}}).then(s=>{mic=s;log('Voice Cleaner включён локально')}).catch(()=>log('Микрофон недоступен'))}
async function api(action,text){if(!$('#ai').checked){log('AI отключён настройками');return null}if(!text.trim()){log('Нужен текст/контекст');return null}try{const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':CSRF},body:JSON.stringify({action,text,language:$('#lang').value,target_language:$('#target').value})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Ошибка');$('#result').textContent=d.result||d.message||'Готово';log(action+' выполнен');return d}catch(e){$('#result').textContent=e.message||'Инструмент временно недоступен';log(action+' ошибка');return null}}
async function runTool(kind,card){const input=card.querySelector('[data-input]');const text=input?.value?.trim()||$('#event').value.trim();
if(kind==='mic'){localMic();return}if(kind==='overlay'){screen.classList.toggle('chat-on');card.querySelector('.ct-mini').classList.toggle('active');log('Overlay переключён');return}if(kind==='alerts'){$('#alert').click();return}if(kind==='censor'){$('#blur').click();return}if(kind==='clips'){log('Момент отмечен: '+(text||'stream-moment'));await api('clip_note',text||'stream moment');return}if(kind==='analytics'){const rows=[`События: ${events}`,`Экран: ${screen.classList.contains('demo')?'активен':'нет'}`,`Overlay: ${screen.classList.contains('chat-on')?'включён':'выключен'}`,`Blur: ${screen.classList.contains('blurred')?'включён':'выключен'}`];$('#result').textContent=rows.join('\n');log('Локальная аналитика обновлена');return}if(kind==='summary'){await api('summary',text);return}if(kind==='shorts'){await api('shorts',text);return}if(kind==='copilot'){await api('copilot',text);return}if(kind==='translator'){await api('translate',text);return}if(kind==='chat'){await api('chatbot',text);return}if(kind==='moderation'){await api('moderate',text);return}}
function panelHtml(kind,label){let body='';if(kind==='mic')body='<div class="field"><label>Режим</label><select><option>Noise suppression + echo cancellation + auto gain</option></select></div><p style="color:var(--muted);font-size:10px">Аудио остаётся в браузере и не записывается на сервер.</p>';else if(kind==='chat')body='<div class="field"><label>Сообщение зрителя</label><textarea data-input placeholder="Например: когда следующий стрим?"></textarea></div>';else if(kind==='moderation')body='<div class="field"><label>Сообщение для проверки</label><textarea data-input placeholder="Вставь новое сообщение чата"></textarea></div><div class="field"><label>Строгость</label><select><option>Обычная</option><option>Строгая</option><option>Максимально осторожная</option></select></div>';else if(kind==='overlay')body='<div class="field"><label>Прозрачность</label><input type="range" min="30" max="100" value="92" oninput="document.getElementById(\'orr\').value=this.value;document.getElementById(\'orr\').dispatchEvent(new Event(\'input\'))"></div>';else if(kind==='alerts')body='<div class="field"><label>Тип</label><select><option>Donation</option><option>Subscription</option><option>Raid</option></select></div><div class="field"><label>Текст</label><input value="💰 Донат +500 ₽ · Спасибо!" oninput="document.getElementById(\'at\').value=this.value"></div>';else if(kind==='translator')body='<div class="field"><label>Текст</label><textarea data-input placeholder="Текст для перевода"></textarea></div>';else if(kind==='censor')body='<div class="field"><label>Сила Blur</label><input type="range" min="0" max="32" value="18" oninput="document.getElementById(\'br\').value=this.value;document.getElementById(\'br\').dispatchEvent(new Event(\'input\'))"></div>';else if(kind==='clips')body='<div class="field"><label>Название</label><input data-input placeholder="Например: лучший момент раунда"></div>';else if(kind==='copilot')body='<div class="field"><label>Контекст события</label><textarea data-input placeholder="Например: зрители спорят о выборе героя"></textarea></div>';else if(kind==='analytics')body='<p style="color:var(--muted);font-size:10px">Счётчики этой страницы обновляются локально. Никаких постоянных запросов.</p>';else if(kind==='summary')body='<div class="field"><label>Заметки/текст завершённого стрима</label><textarea data-input placeholder="Вставь тезисы или расшифровку"></textarea></div>';else if(kind==='shorts')body='<div class="field"><label>Момент для Shorts</label><textarea data-input placeholder="Опиши момент или вставь текст"></textarea></div>';return `<div class="tool-panel"><h4>${label}</h4><div class="grid">${body}</div><div class="bar"><button class="ct-mini" data-run>▶ ${label}</button></div></div>`}
const tools=$('#tools');toolData.forEach(([ico,name,desc,kind,button,setting])=>{const c=document.createElement('article');c.className='ct-card';c.innerHTML=`<div class="icon">${ico}</div><h3>${name}</h3><p>${desc}</p><div class="card-actions"><button class="ct-mini" data-open>⚙️ Настроить</button><button class="ct-mini" data-fast>▶ Запустить</button></div>${panelHtml(kind,setting)}`;tools.appendChild(c);c.querySelector('[data-open]').onclick=()=>{document.querySelectorAll('.ct-card.open').forEach(x=>{if(x!==c)x.classList.remove('open')});c.classList.toggle('open');log(name+' настройки '+(c.classList.contains('open')?'открыты':'закрыты'))};c.querySelector('[data-fast]').onclick=()=>{c.classList.add('open');runTool(kind,c)};c.querySelector('[data-run]').onclick=()=>runTool(kind,c)});
$$('[data-ai]').forEach(b=>b.onclick=()=>api(b.dataset.ai,$('#event').value));
function $$(s){return [...document.querySelectorAll(s)]}
log('Creator Tools готов');
})();
</script>
</body>
</html>
